mapper.select:
SELECT DISTINCT u.* FROM chs.t_user u INNER JOIN chs.t_user_role ur ON u.username = ur.username WHERE NOT EXISTS ( SELECT 1 FROM chs.t_user_role ur2 WHERE ur2.username = u.username AND ur2.role = 'ROLE_ADMIN' )
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.create_time >= #{startDate}
AND u.create_time <= #{endDate}
ORDER BY u.create_time DESC
